window.MAGIC_CHUNK_2 = [{"name":"Ioun Stone Opalescent White Pyramid","aura_strength":"moderate","aura_school":"transmutation","cl":12,"slots":["none"],"groups":["Wondrous Item"],"price":10000,"weight":0,"description":"Each stone of this type is keyed to a particular kind of weapon (heavy flail, light crossbow, shortsword, and so on) and grants you proficiency with that weapon.","requirements":"Craft Wondrous Items, transformation or proficiency in the appropriate weapon, creator must be 12th level","cost":5000,"destruction":null,"base_item":null,"magic_items":null,"source":"Seekers of Secrets","pfs_content":0},{"name":"Ioun Stone Pale Ruby Trillian","aura_strength":"moderate","aura_school":"transmutation","cl":12,"slots":["none"],"groups":["Wondrous Item"],"price":5000,"weight":0,"description":"This stone grants you a +5 competence bonus on Stealth checks.","requirements":"Craft Wondrous Items, cat's grace, creator must be 12th level","cost":2500,"destruction":null,"base_item":null,"magic_items":null,"source":"Seekers of Secrets","pfs_content":0},{"name":"Ioun Stone Scarlet and Green Cabochon","aura_strength":"moderate","aura_school":"transmutation","cl":12,"slots":["none"],"groups":["Wondrous Item"],"price":10000,"weight":0,"description":"This stone grants you the Endurance feat.","requirements":"Craft Wondrous Items, bull's strength, cat's grace, creator must be 12th level","cost":5000,"destruction":null,"base_item":null,"magic_items":null,"source":"Seekers of Secrets","pfs_content":0},{"name":"Ioun Stone Turquoise Sphere","aura_strength":"moderate","aura_school":"transmutation","cl":12,"slots":["none"],"groups":["Wondrous Item"],"price":6000,"weight":0,"description":"This stone grants you a +5 competence bonus on Ride checks. Any horse or pony you ride gains the benefits of the Fleet feat.","requirements":"Craft Wondrous Items, charm animal, longstrider, creator must be 12th level","cost":3000,"destruction":null,"base_item":null,"magic_items":null,"source":"Seekers of Secrets","pfs_content":0},{"name":"Ioun Stone Vermilion Rhomboid","aura_strength":"moderate","aura_school":"transmutation","cl":12,"slots":["none"],"groups":["Wondrous Item"],"price":10000,"weight":0,"description":"This stone grants you a +5 competence bonus on Acrobatics and Swim checks.","requirements":"Craft Wondrous Items, bull's strength, cat's grace, creator must be 12th level","cost":5000,"destruction":null,"base_item":null,"magic_items":null,"source":"Seekers of Secrets","pfs_content":0},{"name":"Wayfinder, Standard","aura_strength":"faint","aura_school":"evocation","cl":5,"slots":["none"],"groups":["Wondrous Item"],"price":500,"weight":0,"description":"A small magical device patterned off ancient relics of the Azlanti, a wayfinder is typically made from silver and bears gold accents. With a command word, you can use a wayfinder to shine (as the light spell). The wayfinder also acts as a nonmagical (magnetic) compass, granting you a +2 circumstance bonus on Survival checks to avoid becoming lost. All wayfinders include a small indentation designed to hold a single ioun stone. An ioun stone slotted in this manner grants you its normal benefits (as if it were orbiting your head), but frequently reveals entirely new powers due to the magic of the wayfinder itself.","requirements":"Craft Wondrous Items, light","cost":250,"destruction":null,"base_item":null,"magic_items":null,"source":"Seekers of Secrets","pfs_content":0},{"name":"Wayfinder of Passage","aura_strength":"moderate","aura_school":"varies","cl":10,"slots":["none"],"groups":["Wondrous Item"],"price":136000,"weight":0,"description":"This wayfinder is an artistic treasure, crafted in gold and set with tiny opals, rubies, diamonds, and sapphires. Three slots on the inner side of the lid can each hold one ioun stone. It sheds light equivalent to the daylight spell on your command. It has the following abilities, each activated by a different command word:\n- dimension door (once per day)\n- feather fall (at will)\n- knock (at will)\n- resist energy (once per day, energy resistance 20, lasts 24 hours) When the first ioun stone slot is used, the dimension door ability no longer functions. When the second slot is used, feather fall and resist energy are unavailable. When the third slot is used, daylight and knock no longer function.","requirements":"Craft Wondrous Items, daylight, dimension door, feather fall, knock, resist energy","cost":68000,"destruction":null,"base_item":null,"magic_items":null,"source":"Seekers of Secrets","pfs_content":0},{"name":"Wayfinder of the Sleeping Eye","aura_strength":"strong","aura_school":"illusion","cl":13,"slots":["none"],"groups":["Wondrous Item"],"price":70000,"weight":0,"description":"This exquisitely crafted wayfinder bears the design of a half-closed eye in platinum and mithral. The eye is a socket for an ioun stone; when filled, you may activate the wayfinder when you sleep or meditate to create a mobile illusory image of yourself that is partly real. You control the image as if it were your own body and perceive things through it as if it had all of your normal senses plus darkvision with a range of 60 feet. You don't need to maintain line of sight to the image. The image is visible but transparent, and it cannot perform any action that an unseen servant is unable to perform. The image has 40% of your hit points at the time it was created. Its AC is 10 + your size modifier + your Dexterity modifier. It uses your current Will saving throw bonus but automatically fails Fortitude and Reflex saves. It is destroyed if brought to 0 hit points, which deals you 2d4 points of Charisma damage. It can be dispelled, and cannot enter areas warded against summoned creatures, your alignment, illusions, or incorporeal creatures. You may end this ability as a free action, and it ends automatically if you are awakened, your body is attacked, or 8 hours pass; ending the image in this manner doesn't deal you Charisma damage. Using this ability drains energy from the slotted ioun stone, rendering it dull gray and powerless for 24 hours. A dull gray ioun stone cannot power the projection ability of this wayfinder. The wayfinder can still have synergistic powers granted by an ioun stone, though they don't function while the slotted stone is powerless.","requirements":"Craft Wondrous Items, arcane eye, shadow conjuration","cost":35000,"destruction":null,"base_item":null,"magic_items":null,"source":"Seekers of Secrets","pfs_content":0},{"name":"Autonomous Cartographer","aura_strength":"faint","aura_school":"divination","cl":5,"slots":["none"],"groups":["Wondrous Item"],"price":2000,"weight":0,"description":"Upon command, this item draws your surroundings, out to the limits of your normal vision, rendering them as if depicted by a competent but unexceptional artist. It doesn't record any details you cannot see. The autonomous cartographer creates the map as needed to fit upon a 1-foot by 4-foot parchment or scroll contained within the item. A second command erases the scroll, allowing you to use it again. You may insert or remove a scroll as a full-round action.","requirements":"Craft Wondrous Items, erase, prestidigitation","cost":1000,"destruction":null,"base_item":null,"magic_items":null,"source":"Seekers of Secrets","pfs_content":0},{"name":"Dead Man's Shroud","aura_strength":"faint","aura_school":"necromancy","cl":5,"slots":["shoulders"],"groups":["Wondrous Item"],"price":6000,"weight":0,"description":"This dirt-stained cloak was woven in shadow from the burial shroud of a condemned murderer. It prevents nonintelligent undead from detecting you, as per the hide from undead spell. Intelligent undead can perceive you if they succeed at a DC 11 Will save. The warding is ended if you touch an undead creature, channel energy against undead, or attack any creature. Once per day as a standard action you can silently call forth the shadows bound into the shroud, rendering you invisible for 5 minutes.","requirements":"Craft Wondrous Items, hide from undead, invisibility","cost":3000,"destruction":null,"base_item":null,"magic_items":null,"source":"Seekers of Secrets","pfs_content":0},{"name":"Eldritch Egress","aura_strength":"moderate","aura_school":"transmutation","cl":9,"slots":["none"],"groups":["Wondrous Item"],"price":10000,"weight":0,"description":"This cunningly designed bundle of wooden slats unfolds and interlocks to form a 3-foot by 3-foot frame. Once per day you may place the unfolded frame upon a solid surface to form a passage up to 10 feet deep, as if using a passwall spell. The passageway lasts for 1 hour unless the frame is removed earlier. Folding or unfolding the frame is a full-round action that provokes attacks of opportunity. Using the unfolded frame to create a passage is a standard action. Medium or smaller creatures can easily pass through the tunnel, while Large creatures require an Escape Artist check. The eldritch egress can only be removed from outside the surface it was placed on, so careful planning is required when using it.","requirements":"Craft Wondrous Items, passwall","cost":5000,"destruction":null,"base_item":null,"magic_items":null,"source":"Seekers of Secrets","pfs_content":0},{"name":"Horseshoes of Great Burden","aura_strength":"faint","aura_school":"transmutation","cl":3,"slots":["feet"],"groups":["Wondrous Item"],"price":2500,"weight":0,"description":"These sturdy iron horseshoes come in sets of four like ordinary horseshoes, but are much heavier. When affixed to an animal's hooves, they double the animal's carrying capacity. All four shoes must be worn by the same animal for the magic to be effective.","requirements":"Craft Wondrous Items, bear's endurance, bull's strength","cost":1250,"destruction":null,"base_item":null,"magic_items":null,"source":"Seekers of Secrets","pfs_content":0},{"name":"Pathfinder Pouch","aura_strength":"none","aura_school":"none","cl":9,"slots":["none"],"groups":["Wondrous Item"],"price":1000,"weight":0,"description":"This nondescript belt pouch is quite popular among Pathfinders who need to smuggle items past snooping guards or government officials. Detect magic doesn't detect that it is magical (as per the magic aura spell), but the pouch acts as a very small bag of holding (contents limit 10 pounds, volume limit 2 cubic feet). With a command word, the wearer can close or open the extradimensional space within the pouch; when closed, the pouch holds no more than a mundane belt pouch the size of a human fist, though objects within the extradimensional space remain stored, unreachable until the pouch is unsealed again. This allows the user to empty his pockets or even turn the pouch inside-out to prove he carries no contraband, and access the hidden goods later when in a safe place. Because of their nonmagical auras, these pouches sometimes hold secret treasures for generations without their owners realizing their nature.","requirements":"Craft Wondrous Items, magic aura, secret chest","cost":1000,"destruction":null,"base_item":null,"magic_items":null,"source":"Seekers of Secrets","pfs_content":0},{"name":"Versatile Vest","aura_strength":"moderate","aura_school":"conjuration and transmutation","cl":9,"slots":["chest"],"groups":["Wondrous Item"],"price":2000,"weight":0,"description":"This sturdy vest stays dry and spotless in the worst of conditions. You can secure up to six objects (weighing up to 1 pound each) to the vest by holding them to it and speaking a command word. You can retrieve any of these items as a move action. In addition, the vest has four large pockets, each capable of holding as much as 1/2 cubic foot in volume or 5 pounds in weight, and weighing only 1 pound when full. When closed, the pockets are proof against water and the elements. The first pocket contains 1 day's worth of trail rations, a quart of water in a waterskin, two candles, and a tindertwig. The vest recreates these items if the first pocket is left empty for 3 days.","requirements":"Craft Wondrous Items, create food and water, prestidigitation, secret chest","cost":1000,"destruction":null,"base_item":null,"magic_items":null,"source":"Seekers of Secrets","pfs_content":0},{"name":"Blade of the Willing Martyr","aura_strength":"strong","aura_school":"necromancy","cl":18,"slots":["chest"],"groups":["Weapon"],"price":150000,"weight":0,"description":"Even the Pathfinders cannot say which tale of this item's origins is true; it may have been made from a piece of the Pact Stone, carried by Norgorber as he achieved apotheosis, or forged in the depths of Orv and quenched in its maker's heartblood. This silver slender athame is deceptively plain, but has a treacherous past. It has been credited with deeds as noble as ending the life of the annis witch Traxyla of the Eye of Law (slain even as the blade's owner Ioella was beheaded by Madame Margaery) and as petty as the murder of Karian (loving mother and priestess of Sarenrae) by her estranged and vengeful husband. The blade of the willing martyr is a +3 keen vicious dagger, but its greatest power can only be invoked outside of battle. To activate this power you must spill your blood on your target, an object belonging to the target, or a physical token of the target's body (such as a few strands of hair). Your target gets a DC 23 Will save (using the same saving throw modifiers as the scrying spell for the owner's knowledge and connection to the victim) to avoid the effect, which forges a link between you and the target. Once you forge a link, your soul and the target's soul are intertwined. Should you die, your target dies, suffering the same apparent injuries and symptoms; likewise, you die if your target dies. The link may only be severed by break enchantment or remove curse.","requirements":"Craft Magic Arms and Armor, enervation, keen edge, symbol of death","cost":75000,"destruction":null,"base_item":"+3 keen vicious dagger","magic_items":null,"source":"Seekers of Secrets","pfs_content":0},{"name":"Ioun Stone, Mindborer","aura_strength":"strong","aura_school":"transmutation","cl":12,"slots":["none"],"groups":["Weapon"],"price":0,"weight":0,"description":"This cursed item looks like any normal ioun stone, and has powers according to its color and shape. However, whenever you are in combat, the orbiting stone batters at your face and head, dealing 1 hit point of damage each round. If you sleep or fall unconscious while the stone is in orbit, it drills into your head, dealing 1 point of Intelligence, Wisdom, and Charisma damage each round until the penalty to one of these ability scores exceeds your actual score, at which point it removes itself from your head and hides itself on your person, near other gems. The stone can remove itself from a wayfinder to attack you in this fashion. The attack automatically wakes a sleeping character. The only way to end the attack is to interfere with the magic of the stone (by using dispel magic, entering an antimagic field, and so on) or grab it and place it in a container.","requirements":"Craft Magic Arms and Armor, creator must be 12th level","cost":0,"destruction":null,"base_item":null,"magic_items":null,"source":"Seekers of Secrets","pfs_content":0},{"name":"Ioun Stone Sepia Ellipsoid","aura_strength":"strong","aura_school":"abjuration","cl":18,"slots":["none"],"groups":["Weapon"],"price":68000,"weight":0,"description":"This dark stone sometimes appears to be made of transparent crystal filled nearly to the brim with dark ink. It provides the benefits of an iridescent spindle (sustains you without air), pearly white spindle (regenerate 1 hit point per 10 minutes), and an orange prism (+1 caster level). However, it has two drawbacks. First, once set loose to orbit your head, it dislikes being contained (including being placed in a wayfinder) and frees itself to orbit again 1d4+1 hours after being removed from its spinning path. Second, it drains the power out of other ioun stones, rendering them dull gray and powerless at a rate of one every 24 hours. Thus, it is an excellent and valuable item if you only have one ioun stone, but hard to conceal and dangerous to your other treasures. A remove curse or similar spell can put the stone at rest and prevent it from returning to its orbit. The Society has at least three specimens of this type locked in the Vaults to prevent ignorant Pathfinders from ruining perfectly good ioun stones. In theory you could place one directly into a wayfinder rather than ever letting it orbit, though conflicting reports suggest the sepia ellipsoid may be able to drain power out of orbiting stones even when contained in this way. The specimens in the Vaults are carefully locked in lead boxes to prevent them from draining the powers of other stored ioun stones.","requirements":"Craft Magic Arms and Armor, mage's disjunction, regenerate, water breathing, creator must be 12th level","cost":34000,"destruction":null,"base_item":null,"magic_items":null,"source":"Seekers of Secrets","pfs_content":0},{"name":"Crystal Ball, Standard","aura_strength":"moderate","aura_school":"divination","cl":10,"slots":["none"],"groups":["Wondrous Item"],"price":42000,"weight":7,"description":"This is the most common form of scrying device, a crystal sphere about 6 inches in diameter. So well-known are these items that many so-called oracles or fortune-tellers use similar appearing (but completely non-magical) replicas of these items to ply their trades. A character can use a magical crystal ball to see over virtually any distance or into other planes of existence, as with the spell scrying (Will DC 16 negates). A crystal ball can be used multiple times per day, but the DC to resist its power decreases by 1 for each additional use.","requirements":"Craft Wondrous Items, scrying","cost":21000,"destruction":null,"base_item":null,"magic_items":null,"source":"Core Rulebook","pfs_content":0},{"name":"Figurine of Wondrous Power, Bronze Griffon","aura_strength":"moderate","aura_school":"transmutation","cl":11,"slots":["none"],"groups":["Wondrous Item"],"price":10000,"weight":1,"description":"Each of the several kinds of figurines of wondrous power appears to be a miniature statuette of a creature an inch or so high (with one exception). When the figurine is tossed down and the correct command word spoken, it becomes a living creature of normal size (except when noted otherwise below). The creature obeys and serves its owner. Unless stated otherwise, the creature understands Common but doesn't speak. If a figurine of wondrous power is broken or destroyed in its statuette form, it is forever ruined. All magic is lost, its power departed. If slain in animal form, the figurine simply reverts to a statuette that can be used again at a later time. Bronze Griffon: When animated, a bronze griffon acts in all ways like a normal griffon under the command of its possessor. The item can be used twice per week for up to 6 hours per use. When 6 hours have passed or when the command word is spoken, the bronze griffon once again becomes a tiny statuette.","requirements":"Craft Wondrous Items, animate objects","cost":5000,"destruction":null,"base_item":null,"magic_items":null,"source":"Core Rulebook","pfs_content":0},{"name":"Figurine of Wondrous Power, Ebony Fly","aura_strength":"moderate","aura_school":"transmutation","cl":11,"slots":["none"],"groups":["Wondrous Item"],"price":10000,"weight":1,"description":"Each of the several kinds of figurines of wondrous power appears to be a miniature statuette of a creature an inch or so high (with one exception). When the figurine is tossed down and the correct command word spoken, it becomes a living creature of normal size (except when noted otherwise below). The creature obeys and serves its owner. Unless stated otherwise, the creature understands Common but doesn't speak. If a figurine of wondrous power is broken or destroyed in its statuette form, it is forever ruined. All magic is lost, its power departed. If slain in animal form, the figurine simply reverts to a statuette that can be used again at a later time. Ebony Fly: When animated, an ebony fly is the size of a pony and has all the statistics of a pegasus but can make no attacks. The item can be used three times per week for up to 12 hours per use. When 12 hours have passed or when the command word is spoken, the ebony fly again becomes a tiny statuette.","requirements":"Craft Wondrous Items, animate objects","cost":5000,"destruction":null,"base_item":null,"magic_items":null,"source":"Core Rulebook","pfs_content":0},{"name":"Figurine of Wondrous Power, Golden Lions","aura_strength":"moderate","aura_school":"transmutation","cl":11,"slots":["none"],"groups":["Wondrous Item"],"price":16500,"weight":1,"description":"Each of the several kinds of figurines of wondrous power appears to be a miniature statuette of a creature an inch or so high (with one exception). When the figurine is tossed down and the correct command word spoken, it becomes a living creature of normal size (except when noted otherwise below). The creature obeys and serves its owner. Unless stated otherwise, the creature understands Common but doesn't speak. If a figurine of wondrous power is broken or destroyed in its statuette form, it is forever ruined. All magic is lost, its power departed. If slain in animal form, the figurine simply reverts to a statuette that can be used again at a later time. Golden Lions: These figurines come in pairs. They become normal adult male lions. If slain in combat, the lions cannot be brought back from statuette form for 1 full week. Otherwise, they can be used once per day for up to 1 hour. They enlarge and shrink upon speaking the command word.","requirements":"Craft Wondrous Items, animate objects","cost":8250,"destruction":null,"base_item":null,"magic_items":null,"source":"Core Rulebook","pfs_content":0},{"name":"Figurine of Wondrous Power, Ivory Goats","aura_strength":"moderate","aura_school":"transmutation","cl":11,"slots":["none"],"groups":["Wondrous Item"],"price":21000,"weight":1,"description":"Each of the several kinds of figurines of wondrous power appears to be a miniature statuette of a creature an inch or so high (with one exception). When the figurine is tossed down and the correct command word spoken, it becomes a living creature of normal size (except when noted otherwise below). The creature obeys and serves its owner. Unless stated otherwise, the creature understands Common but doesn't speak. If a figurine of wondrous power is broken or destroyed in its statuette form, it is forever ruined. All magic is lost, its power departed. If slain in animal form, the figurine simply reverts to a statuette that can be used again at a later time. Ivory Goats: These figurines come in threes. Each goat of this trio looks slightly different from the others, and each has a different function:\n- The Goat of Traveling: This statuette provides a speedy and enduring mount equal to that of a heavy horse in every way except appearance. The goat can travel for a maximum of 1 day each week-continuously or in any combination of periods totaling 24 hours. At this point, or when the command word is uttered, it returns to its statuette form for no less than 1 day before it can again be used.\n- The Goat of Travail: This statuette becomes an enormous creature, larger than a bull, with the statistics of a nightmare except for the addition of a pair of wicked horns of exceptional size (damage 1d8+4 for each horn). If it is charging to attack, it may only use its horns (but add 6 points of damage to each successful attack in that round). It can be called to life just once per month for up to 12 hours at a time.\n- The Goat of Terror: When called upon with the proper command word, this statuette becomes a destrier-like mount with the statistics of a light horse. However, its rider can employ the goat's horns as weapons (one horn as a +3 heavy lance, the other as a +5 longsword). When ridden in an attack against an opponent, the goat of terror radiates fear as the spell in a 30-foot radius (Will DC 16 partial). It can be used once every 2 weeks for up to 3 hours per use.","requirements":"Craft Wondrous Items, animate objects","cost":10500,"destruction":null,"base_item":null,"magic_items":null,"source":"Core Rulebook","pfs_content":0},{"name":"Figurine of Wondrous Power, Marble Elephant","aura_strength":"moderate","aura_school":"transmutation","cl":11,"slots":["none"],"groups":["Wondrous Item"],"price":17000,"weight":1,"description":"Each of the several kinds of figurines of wondrous power appears to be a miniature statuette of a creature an inch or so high (with one exception). When the figurine is tossed down and the correct command word spoken, it becomes a living creature of normal size (except when noted otherwise below). The creature obeys and serves its owner. Unless stated otherwise, the creature understands Common but doesn't speak. If a figurine of wondrous power is broken or destroyed in its statuette form, it is forever ruined. All magic is lost, its power departed. If slain in animal form, the figurine simply reverts to a statuette that can be used again at a later time. Marble Elephant: This is the largest of the figurines, the statuette being about the size of a human hand. Upon utterance of the command word, a marble elephant grows to the size and specifications of a true elephant. The animal created from the statuette is fully obedient to the figurine's owner, serving as a beast of burden, a mount, or a combatant. The statuette can be used four times per month for up to 24 hours at a time.","requirements":"Craft Wondrous Items, animate objects","cost":8500,"destruction":null,"base_item":null,"magic_items":null,"source":"Core Rulebook","pfs_content":0},{"name":"Figurine of Wondrous Power, Obsidian Steed","aura_strength":"strong","aura_school":"conjuration and transmutation","cl":15,"slots":["none"],"groups":["Wondrous Item"],"price":28500,"weight":1,"description":"Each of the several kinds of figurines of wondrous power appears to be a miniature statuette of a creature an inch or so high (with one exception). When the figurine is tossed down and the correct command word spoken, it becomes a living creature of normal size (except when noted otherwise below). The creature obeys and serves its owner. Unless stated otherwise, the creature understands Common but doesn't speak. If a figurine of wondrous power is broken or destroyed in its statuette form, it is forever ruined. All magic is lost, its power departed. If slain in animal form, the figurine simply reverts to a statuette that can be used again at a later time. Obsidian Steed: This figurine appears to be a small, shapeless lump of black stone. Only careful inspection reveals that it vaguely resembles some form of quadruped. On command, the nearformless piece of obsidian becomes a fantastic mount. Treat it as a heavy horse with the following additional powers usable once per round at will: overland flight, plane shift, and ethereal jaunt. The steed allows itself to be ridden, but if the rider is of good alignment, the steed is 10% likely per use to carry him to the lower planes and then return to its statuette form. The statuette can be used once per week for one continuous period of up to 24 hours. Note that when an obsidian steed becomes ethereal or plane shifts, its rider and his gear follow suit. Thus, the user can travel to other planes via this means.","requirements":"Craft Wondrous Items, animate objects, etherealness, fly, plane shift","cost":14250,"destruction":null,"base_item":null,"magic_items":null,"source":"Core Rulebook","pfs_content":0},{"name":"Figurine of Wondrous Power, Onyx Dog","aura_strength":"moderate","aura_school":"transmutation","cl":11,"slots":["none"],"groups":["Wondrous Item"],"price":15500,"weight":1,"description":"Each of the several kinds of figurines of wondrous power appears to be a miniature statuette of a creature an inch or so high (with one exception). When the figurine is tossed down and the correct command word spoken, it becomes a living creature of normal size (except when noted otherwise below). The creature obeys and serves its owner. Unless stated otherwise, the creature understands Common but doesn't speak. If a figurine of wondrous power is broken or destroyed in its statuette form, it is forever ruined. All magic is lost, its power departed. If slain in animal form, the figurine simply reverts to a statuette that can be used again at a later time. Onyx Dog: When commanded, this statuette changes into a creature with the same properties as a riding dog except that it is endowed with an Intelligence of 8, can communicate in Common, and has exceptional olfactory and visual abilities. It has the scent ability and adds +4 on its Perception checks. It has 60- foot darkvision, and it can see invisibility. An onyx dog can be used once per week for up to 6 hours. It obeys only its owner.","requirements":"Craft Wondrous Items, animate objects","cost":7750,"destruction":null,"base_item":null,"magic_items":null,"source":"Core Rulebook","pfs_content":0},{"name":"Figurine of Wondrous Power, Serpentine Owl","aura_strength":"moderate","aura_school":"transmutation","cl":11,"slots":["none"],"groups":["Wondrous Item"],"price":9100,"weight":1,"description":"Each of the several kinds of figurines of wondrous power appears to be a miniature statuette of a creature an inch or so high (with one exception). When the figurine is tossed down and the correct command word spoken, it becomes a living creature of normal size (except when noted otherwise below). The creature obeys and serves its owner. Unless stated otherwise, the creature understands Common but doesn't speak. If a figurine of wondrous power is broken or destroyed in its statuette form, it is forever ruined. All magic is lost, its power departed. If slain in animal form, the figurine simply reverts to a statuette that can be used again at a later time. Serpentine Owl: This figurine becomes either a normal-sized horned owl or a giant owl (use the stats for the giant eagle) according to the command word used. The transformation can take place once per day, with a maximum duration of 8 continuous hours. However, after three transformations into giant owl form, the statuette loses all its magical properties. The owl communicates with its owner by telepathic means, informing him of all it sees and hears.","requirements":"Craft Wondrous Items, animate objects","cost":4450,"destruction":null,"base_item":null,"magic_items":null,"source":"Core Rulebook","pfs_content":0},{"name":"Figurine of Wondrous Power, Silver Raven","aura_strength":"moderate","aura_school":"enchantment and transmutation","cl":6,"slots":["none"],"groups":["Wondrous Item"],"price":3800,"weight":1,"description":"Each of the several kinds of figurines of wondrous power appears to be a miniature statuette of a creature an inch or so high (with one exception). When the figurine is tossed down and the correct command word spoken, it becomes a living creature of normal size (except when noted otherwise below). The creature obeys and serves its owner. Unless stated otherwise, the creature understands Common but doesn't speak. If a figurine of wondrous power is broken or destroyed in its statuette form, it is forever ruined. All magic is lost, its power departed. If slain in animal form, the figurine simply reverts to a statuette that can be used again at a later time. Silver Raven: This silver figurine turns into a raven on command (but it retains its metallic consistency, which gives it hardness 10). Another command sends it off into the air, bearing a message just like a creature affected by an animal messenger spell. If not commanded to carry a message, the raven obeys the commands of its owner, although it has no special powers or telepathic abilities. It can maintain its nonfigurine status for only 24 hours per week, but the duration need not be continuous.","requirements":"Craft Wondrous Items, animal messenger, animate objects","cost":1900,"destruction":null,"base_item":null,"magic_items":null,"source":"Core Rulebook","pfs_content":0},{"name":"Strand of Prayer Beads, Lesser","aura_strength":"faint","aura_school":"varies","cl":5,"slots":["none"],"groups":["Wondrous Item"],"price":9600,"weight":0.5,"description":"This item appears to be nothing more than a string of prayer beads until the owner casts a divine spell while the beads are carried. Once that occurs, the owner instantly knows the powers of the prayer beads and understands how to activate the strand's special magical beads.\n\nEach special bead can be used once per day, except for the bead of summons, which works only once and then becomes nonmagical. The beads of blessing, smiting, and wind walking function as spell trigger items; the beads of karma and summons can be activated by any character capable of casting divine spells. The owner need not hold or wear the strand of prayer beads in any specific location, as long as he carries it somewhere on his person.\n\nEach strand includes two or more special beads, each with a different magic power selected from the following list. A lesser strand of prayer beads has a bead of blessing and a bead of healing.\n\n>>Special Bead Type / Special Bead Ability\nBead of blessing (CL 1st) | Wearer can cast bless.\nBead of healing (CL 5th) | Wearer can cast his choice of cure serious wounds, remove blindness/deafness, or remove disease.\nBead of karma (CL 9th) | Wearer casts his spells at +4 caster level. Effect lasts 10 minutes.\nBead of smiting (CL 7th) | Wearer can cast chaos hammer, holy smite, order's wrath, or unholy blight (Will DC 17 partial).\nBead of summons (CL 17th) | Summons a powerful creature of appropriate alignment from the Outer Planes (an angel, devil, etc.) to aid the wearer for 1 day. (If the wearer uses the bead of summons to summon a deity's emissary frivolously, the deity takes that character's items and places a geas upon him as punishment at the very least.)\nBead of wind walking (CL 11th) | Wearer can cast wind walk.\n\nThe power of a special bead is lost if it is removed from the strand. Reduce the price of a strand of prayer beads that is missing one or more beads by the following amounts: bead of blessing –600 gp, bead of healing –9,000 gp, bead of karma –20,000 gp, bead of smiting –16,800 gp, bead of summons –20,000 gp, bead of wind walking –46,800 gp.","requirements":"Craft Wondrous Items and one of the following spells per bead, as appropriate: bless (blessing), cure serious wounds, remove blindness/ deafness, or remove disease (healing)","cost":4800,"destruction":null,"base_item":null,"magic_items":null,"source":"Core Rulebook","pfs_content":0},{"name":"Strand of Prayer Beads, Standard","aura_strength":"moderate","aura_school":"varies","cl":9,"slots":["none"],"groups":["Wondrous Item"],"price":45800,"weight":0.5,"description":"This item appears to be nothing more than a string of prayer beads until the owner casts a divine spell while the beads are carried. Once that occurs, the owner instantly knows the powers of the prayer beads and understands how to activate the strand's special magical beads.\n\nEach special bead can be used once per day, except for the bead of summons, which works only once and then becomes nonmagical. The beads of blessing, smiting, and wind walking function as spell trigger items; the beads of karma and summons can be activated by any character capable of casting divine spells. The owner need not hold or wear the strand of prayer beads in any specific location, as long as he carries it somewhere on his person.\n\nEach strand includes two or more special beads, each with a different magic power selected from the following list. A strand of prayer beads has a bead of healing, a bead of karma, and a bead of smiting.\n\n>>Special Bead Type / Special Bead Ability\nBead of blessing (CL 1st) | Wearer can cast bless.\nBead of healing (CL 5th) | Wearer can cast his choice of cure serious wounds, remove blindness/deafness, or remove disease.\nBead of karma (CL 9th) | Wearer casts his spells at +4 caster level. Effect lasts 10 minutes.\nBead of smiting (CL 7th) | Wearer can cast chaos hammer, holy smite, order's wrath, or unholy blight (Will DC 17 partial).\nBead of summons (CL 17th) | Summons a powerful creature of appropriate alignment from the Outer Planes (an angel, devil, etc.) to aid the wearer for 1 day. (If the wearer uses the bead of summons to summon a deity's emissary frivolously, the deity takes that character's items and places a geas upon him as punishment at the very least.)\nBead of wind walking (CL 11th) | Wearer can cast wind walk.\n\nThe power of a special bead is lost if it is removed from the strand. Reduce the price of a strand of prayer beads that is missing one or more beads by the following amounts: bead of blessing –600 gp, bead of healing –9,000 gp, bead of karma –20,000 gp, bead of smiting –16,800 gp, bead of summons –20,000 gp, bead of wind walking –46,800 gp.","requirements":"Craft Wondrous Items and one of the following spells per bead, as appropriate: bless (blessing), cure serious wounds, remove blindness/ deafness, or remove disease (healing), righteous might (karma), chaos hammer, holy smite, order's wrath, or unholy blight (smiting)","cost":22900,"destruction":null,"base_item":null,"magic_items":null,"source":"Core Rulebook","pfs_content":0},{"name":"Strand of Prayer Beads, Greater","aura_strength":"strong","aura_school":"varies","cl":17,"slots":["none"],"groups":["Wondrous Item"],"price":95800,"weight":0.5,"description":"This item appears to be nothing more than a string of prayer beads until the owner casts a divine spell while the beads are carried. Once that occurs, the owner instantly knows the powers of the prayer beads and understands how to activate the strand's special magical beads.\n\nEach special bead can be used once per day, except for the bead of summons, which works only once and then becomes nonmagical. The beads of blessing, smiting, and wind walking function as spell trigger items; the beads of karma and summons can be activated by any character capable of casting divine spells. The owner need not hold or wear the strand of prayer beads in any specific location, as long as he carries it somewhere on his person.\n\nEach strand includes two or more special beads, each with a different magic power selected from the following list. A greater strand of prayer beads has a bead of healing, a bead of karma, a bead of summons, and a bead of wind walking.\n\n>>Special Bead Type / Special Bead Ability\nBead of blessing (CL 1st) | Wearer can cast bless.\nBead of healing (CL 5th) | Wearer can cast his choice of cure serious wounds, remove blindness/deafness, or remove disease.\nBead of karma (CL 9th) | Wearer casts his spells at +4 caster level. Effect lasts 10 minutes.\nBead of smiting (CL 7th) | Wearer can cast chaos hammer, holy smite, order's wrath, or unholy blight (Will DC 17 partial).\nBead of summons (CL 17th) | Summons a powerful creature of appropriate alignment from the Outer Planes (an angel, devil, etc.) to aid the wearer for 1 day. (If the wearer uses the bead of summons to summon a deity's emissary frivolously, the deity takes that character's items and places a geas upon him as punishment at the very least.)\nBead of wind walking (CL 11th) | Wearer can cast wind walk.\n\nThe power of a special bead is lost if it is removed from the strand. Reduce the price of a strand of prayer beads that is missing one or more beads by the following amounts: bead of blessing –600 gp, bead of healing –9,000 gp, bead of karma –20,000 gp, bead of smiting –16,800 gp, bead of summons –20,000 gp, bead of wind walking –46,800 gp.","requirements":"Craft Wondrous Items and one of the following spells per bead, as appropriate: bless (blessing), cure serious wounds, remove blindness/ deafness, or remove disease (healing), righteous might (karma), gate (summons), chaos hammer, holy smite, order's wrath, or unholy blight (smiting), wind walk (wind walking)","cost":47900,"destruction":null,"base_item":null,"magic_items":null,"source":"Core Rulebook","pfs_content":0},{"name":"Slaying Arrow, Greater","aura_strength":"strong","aura_school":"necromancy","cl":13,"slots":["none"],"groups":["Ammunition"],"price":4057,"weight":0.1,"description":"This +1 arrow is keyed to a particular type or subtype of creature. If it strikes such a creature, the target must make a DC 20 Fortitude save or take 50 points of damage. Note that even creatures normally exempt from Fortitude saves (undead and constructs) are subject to this attack. When keyed to a living creature, this is a death effect (and thus death ward protects a target). To determine the type or subtype of creature the arrow is keyed to, roll on the table below. A greater slaying arrow functions just like a normal slaying arrow, but the DC to avoid the death effect is 23 and the arrow deals 100 points of damage if the saving throw is failed.\n\n>>d% / Designated Type or Subtype\n01-05 | Aberrations\n06-09 | Animals\n10-16 | Constructs\n17-27 | Dragons\n28-32 | Fey\n33 | Humanoids, aquatic\n34-35 | Humanoids, dwarf\n36-37 | Humanoids, elf\n38-44 | Humanoids, giant\n45 | Humanoids, gnoll\n46 | Humanoids, gnome\n47-49 | Humanoids, goblinoid\n50 | Humanoids, halfling\n51-54 | Humanoids, human\n55-57 | Humanoids, reptilian\n58-60 | Humanoids, orc\n61-65 | Magical beasts\n66-70 | Monstrous humanoids\n71-72 | Oozes\n73 | Outsiders, air\n74-76 | Outsiders, chaotic\n77 | Outsiders, earth\n78-80 | Outsiders, evil\n81 | Outsiders, fire\n82-84 | Outsiders, good\n85-87 | Outsiders, lawful\n88 | Outsiders, water\n89-90 | Plants\n91-98 | Undead\n99-100 | Vermin","requirements":"Craft Magic Arms and Armor, heightened finger of death","cost":2032,"destruction":null,"base_item":"+1 arrow","magic_items":null,"source":"Core Rulebook","pfs_content":0},{"name":"Talon Sword","aura_strength":"moderate","aura_school":"abjuration","cl":8,"slots":["none"],"groups":["Weapon"],"price":19515,"weight":6,"description":"Weapons like this alchemical silver +2 defending bastard sword are favored blades of the Eagle Knights. Easily recognized by its notched blades and golden quillons crafted like upswept eagle wings, its defending ability also protects the wielder's mount.","requirements":"Craft Magic Arms and Armor, shield or shield of faith, shield other","cost":10015,"destruction":null,"base_item":"+2 silver defending bastard sword","magic_items":null,"source":"Andoran","pfs_content":0},{"name":"Talon Sword, Talonstrike","aura_strength":"moderate","aura_school":"abjuration","cl":8,"slots":["none"],"groups":["Weapon"],"price":38715,"weight":6,"description":"Weapons like this alchemical silver +2 defending bastard sword are favored blades of the Eagle Knights. Easily recognized by its notched blades and golden quillons crafted like upswept eagle wings, its defending ability also protects the wielder's mount. Wealthier Eagle Knights who frequently skirmish on the western border against Chelish fiends sometimes have their swords crafted with the ability to cast dimensional anchor on the target as a free action upon a successful hit.","requirements":"Craft Magic Arms and Armor, dimensional anchor, shield or shield of faith, shield other","cost":19615,"destruction":null,"base_item":"+2 silver defending bastard sword","magic_items":null,"source":"Andoran","pfs_content":0},{"name":"Figurine of Wondrous Power, Serpentine Eagle","aura_strength":"moderate","aura_school":"transmutation","cl":11,"slots":["none"],"groups":["Wondrous Item"],"price":9100,"weight":0,"description":"This Andoren variant of the serpentine owl can be transformed into an eagle or giant eagle but is otherwise identical to the owl figurine. Serpentine eagles are popular among Eagle Knights for scouting and emergency transportation.","requirements":"Craft Wondrous Items, animate objects","cost":4550,"destruction":null,"base_item":null,"magic_items":null,"source":"Andoran","pfs_content":0},{"name":"Feather Token, Floating Feather","aura_strength":"strong","aura_school":"conjuration","cl":12,"slots":["none"],"groups":["Wondrous Item"],"price":450,"weight":0,"description":"Several varieties of these enchanted feathers are popular in Andoran. Floating Feather: This token can be attached to any creature up to 200 pounds, causing a pair of large wings to grow from the target and allowing him to fly (speed 30, average maneuverability) for 1 minute. The token can be attached to an object of up to 200 pounds, which flies straight in a direction indicated by the creature who activates the feather unless the activator uses a move action to redirect its movement. The wings persist for 1 minute.","requirements":"Craft Wondrous Items, major creation","cost":225,"destruction":null,"base_item":null,"magic_items":null,"source":"Andoran","pfs_content":0},{"name":"Feather Token, Lance","aura_strength":"strong","aura_school":"conjuration","cl":12,"slots":["none"],"groups":["Wondrous Item"],"price":150,"weight":0,"description":"Several varieties of these enchanted feathers are popular in Andoran. Lance: This token turns into a white-plumed +1 lance for 1 minute. This token is often used when carrying a large weapon is illegal or impractical.","requirements":"Craft Wondrous Items, major creation","cost":75,"destruction":null,"base_item":null,"magic_items":null,"source":"Andoran","pfs_content":0},{"name":"Feather Token, Sky Hook","aura_strength":"strong","aura_school":"conjuration","cl":12,"slots":["none"],"groups":["Wondrous Item"],"price":200,"weight":0,"description":"Several varieties of these enchanted feathers are popular in Andoran. Sky Hook: This token transforms into a huge disembodied eagle's talon (hardness 5, hp 25) anchored wherever you activate it. The talon can support up to 1,000 pounds and persists for 1 day. The talon can be moved up to 10 feet with a DC 20 Strength check.","requirements":"Craft Wondrous Items, major creation","cost":100,"destruction":null,"base_item":null,"magic_items":null,"source":"Andoran","pfs_content":0},{"name":"Feather Token, Tar and Feathers","aura_strength":"strong","aura_school":"conjuration","cl":12,"slots":["none"],"groups":["Wondrous Item"],"price":600,"weight":0,"description":"Several varieties of these enchanted feathers are popular in Andoran. Tar and Feathers: This token can be directed to float to any point within 60 feet and then burst into a mass of sticky white feathers that adheres to all creatures in a 10-foot radius. The clinging feathers affect creatures in the area as a glitterdust spell.","requirements":"Craft Wondrous Items, major creation","cost":300,"destruction":null,"base_item":null,"magic_items":null,"source":"Andoran","pfs_content":0},{"name":"Feather Token, Returning Raven","aura_strength":"strong","aura_school":"conjuration","cl":12,"slots":["none"],"groups":["Wondrous Item"],"price":800,"weight":0,"description":"Several varieties of these enchanted feathers are popular in Andoran. Returning Raven: A token that transforms into a spectral bird and flies to a designated location within 10 miles and speaks a message in the user's voice of up to 25 words. The returning raven will hover in midair for 1 minute, and if touched during this time it will accept a single new message of up to 25 words and then return to its point of origin and deliver it in the voice of the creature that touched it. The returning raven vanishes after delivering the second message or if no new message is imparted within 1 minute.","requirements":"Craft Wondrous Items, major creation","cost":400,"destruction":null,"base_item":null,"magic_items":null,"source":"Andoran","pfs_content":0},{"name":"Fang of Erebus","aura_strength":"faint","aura_school":"evocation","cl":5,"slots":["none"],"groups":["Weapon"],"price":9501,"weight":2,"description":"This +1 shortspear gleams as if newly polished and shimmers with threads of inlaid gold dust. Strangely light for its size, the shortspear has a range increment of 30 feet. Once per day, the wielder may entreat Mammon as the shortspear deals damage as part of a ranged attack. Doing so causes the area within 30 feet of the creature struck to be affected as per the spell deeper darkness. This darkness lingers at the point where the target was damaged, not moving with the target. In addition, the gold dust embedded in the shortspear sparkles if the spearhead is touched to an object or treasure valued at 1,000 gp or more. The wielder can determine if an object is worth 1,000 gp or more, 10,000 gp or more, or 100,000 gp or more just by observing the level of this scintillation. Once per day, the spear can also be laid on the ground and commanded to point to the most valuable object within 30 feet.","requirements":"Craft Magic Arms and Armor, deeper darkness, identify","cost":4750,"destruction":null,"base_item":"+1 shortspear","magic_items":null,"source":"AP 30","pfs_content":0},{"name":"Nightskin","aura_strength":"moderate","aura_school":"illusion [evil]","cl":10,"slots":["armor"],"groups":["Armor"],"price":53100,"weight":25,"description":"Each of these +2 glamered chain shirts bears a permanent illusion of being a fantastic ebon gown of peerless design or a royal suit of nighted hues. Yet those who see past the illusion find a strange padding within the armor, stitched skins of macabre origins filled with locks of delicate hair, dyed in devil's blood. Those who wear the armor find that they can see in even the most abysmal darkness as per a devil's ability to see in darkness (seeing through even magical darkness as if it were full light). In addition, the wearer finds that he can understand Infernal perfectly, though the armor doesn't grant the ability to speak it. Nightskin is a fundamentally evil armor and any wearer of good alignment is treated as being sickened for as long as the armor is worn.","requirements":"Craft Magic Arms and Armor, major image, true seeing","cost":26550,"destruction":null,"base_item":"+2 glamered chain shirt","magic_items":null,"source":"AP 30","pfs_content":0},{"name":"Stag's Helm","aura_strength":"faint","aura_school":"divination","cl":5,"slots":["head"],"groups":["Wondrous Item"],"price":3500,"weight":3,"description":"This striking helmet is crafted to resemble the skull of a mighty stag. Although made from bone, the antlers and helm are as strong as metal. When worn, the helm greatly enhances eyesight and hearing, granting a +2 competence bonus on Perception checks. In addition, once per day the helm may be called upon to enhance any ranged attack made by the wearer to make an insightful shot. Activating this ability is a free action, and once activated, your next ranged attack against a target within 30 feet is made as if that target were flat-footed against you-this allows a rogue to gain the benefit of sneak attack with this shot. If you don't make a ranged attack within 1 round of activating this power, the insight fades and is wasted for that day. A worshiper of Erastil who wears this helm may utilize the insightful shot ability up to 3 times per day.","requirements":"Craft Wondrous Items, creator must have at least 5 ranks in Perception, true strike","cost":1750,"destruction":null,"base_item":null,"magic_items":null,"source":"AP 31","pfs_content":0},{"name":"Crook of Cildhureen","aura_strength":"moderate","aura_school":"illusion","cl":9,"slots":["none"],"groups":["Staff"],"price":16800,"weight":4,"description":"This twisted and gnarled black oak staff draws upon the formless magic of the Shadow Plane to allow use of the following spells:\n- major image (1 charge)\n- shadow conjuration (2 charges)\n- shadow evocation (3 charges) In addition, the staff can further influence shadow conjuration and shadow evocation spells, whether cast from the staff or the wielder's daily allotment of spells, without increasing the spell's level. By expending extra charges, the wielder can increase the shadowy substance used to form such spells by +10% per charge, up to a maximum of +50%. Using the staff for this purpose doesn't increase the casting time of these spells.","requirements":"Craft Staff, major image, shadow conjuration, shadow evocation","cost":8400,"destruction":null,"base_item":null,"magic_items":null,"source":"Fellnight Queen","pfs_content":0},{"name":"Bag of Concealment Type I","aura_strength":"moderate","aura_school":"conjuration","cl":9,"slots":["none"],"groups":["Wondrous Item"],"price":5000,"weight":15,"description":"A bag of concealment appears to be a common leather sack with a shoulder strap, about 2 feet by 4 feet in size. The bag behaves as a bag of holding, with all the same carrying capacities according to size, except for a few key points. Each bag of concealment is keyed to a specific owner upon creation (and can only be keyed to one person at a time)-should the bag's owner be killed, it becomes keyed to the next person to open it (the currently keyed person can also relinquish this status as a standard action, allowing another creature to become keyed to the bag by opening it). Only the person a bag of concealment is keyed to may access its contents. Any others who look in the bag see only the inside of an empty sack, with dimensions matching the bag's outside measurements, as the true contents are kept separate and undetectable in the bag's magical pocket dimension. Should anything be placed in the empty bag by someone other than the owner, the goods that have been shunted to the pocket dimension cannot be accessed unless the new item is removed. A bag of concealment registers as nonmagical unless successfully identified, as per a permanent version of the spell magic aura. The mouth of a bag of concealment can be stretched to up to four times its normal width, so larger goods may be hidden inside.","requirements":"Craft Wondrous Items, fabricate, magic aura, secret chest","cost":2500,"destruction":null,"base_item":null,"magic_items":null,"source":"Classic Treasures","pfs_content":0},{"name":"Bag of Concealment Type II","aura_strength":"moderate","aura_school":"conjuration","cl":9,"slots":["none"],"groups":["Wondrous Item"],"price":10000,"weight":25,"description":"A bag of concealment appears to be a common leather sack with a shoulder strap, about 2 feet by 4 feet in size. The bag behaves as a bag of holding, with all the same carrying capacities according to size, except for a few key points. Each bag of concealment is keyed to a specific owner upon creation (and can only be keyed to one person at a time)-should the bag's owner be killed, it becomes keyed to the next person to open it (the currently keyed person can also relinquish this status as a standard action, allowing another creature to become keyed to the bag by opening it). Only the person a bag of concealment is keyed to may access its contents. Any others who look in the bag see only the inside of an empty sack, with dimensions matching the bag's outside measurements, as the true contents are kept separate and undetectable in the bag's magical pocket dimension. Should anything be placed in the empty bag by someone other than the owner, the goods that have been shunted to the pocket dimension cannot be accessed unless the new item is removed. A bag of concealment registers as nonmagical unless successfully identified, as per a permanent version of the spell magic aura. The mouth of a bag of concealment can be stretched to up to four times its normal width, so larger goods may be hidden inside.","requirements":"Craft Wondrous Items, fabricate, magic aura, secret chest","cost":5000,"destruction":null,"base_item":null,"magic_items":null,"source":"Classic Treasures","pfs_content":0},{"name":"Bag of Concealment Type III","aura_strength":"moderate","aura_school":"conjuration","cl":9,"slots":["none"],"groups":["Wondrous Item"],"price":14800,"weight":35,"description":"A bag of concealment appears to be a common leather sack with a shoulder strap, about 2 feet by 4 feet in size. The bag behaves as a bag of holding, with all the same carrying capacities according to size, except for a few key points. Each bag of concealment is keyed to a specific owner upon creation (and can only be keyed to one person at a time)-should the bag's owner be killed, it becomes keyed to the next person to open it (the currently keyed person can also relinquish this status as a standard action, allowing another creature to become keyed to the bag by opening it). Only the person a bag of concealment is keyed to may access its contents. Any others who look in the bag see only the inside of an empty sack, with dimensions matching the bag's outside measurements, as the true contents are kept separate and undetectable in the bag's magical pocket dimension. Should anything be placed in the empty bag by someone other than the owner, the goods that have been shunted to the pocket dimension cannot be accessed unless the new item is removed. A bag of concealment registers as nonmagical unless successfully identified, as per a permanent version of the spell magic aura. The mouth of a bag of concealment can be stretched to up to four times its normal width, so larger goods may be hidden inside.","requirements":"Craft Wondrous Items, fabricate, magic aura, secret chest","cost":7400,"destruction":null,"base_item":null,"magic_items":null,"source":"Classic Treasures","pfs_content":0},{"name":"Bag of Concealment Type IV","aura_strength":"moderate","aura_school":"conjuration","cl":9,"slots":["none"],"groups":["Wondrous Item"],"price":20000,"weight":60,"description":"A bag of concealment appears to be a common leather sack with a shoulder strap, about 2 feet by 4 feet in size. The bag behaves as a bag of holding, with all the same carrying capacities according to size, except for a few key points. Each bag of concealment is keyed to a specific owner upon creation (and can only be keyed to one person at a time)-should the bag's owner be killed, it becomes keyed to the next person to open it (the currently keyed person can also relinquish this status as a standard action, allowing another creature to become keyed to the bag by opening it). Only the person a bag of concealment is keyed to may access its contents. Any others who look in the bag see only the inside of an empty sack, with dimensions matching the bag's outside measurements, as the true contents are kept separate and undetectable in the bag's magical pocket dimension. Should anything be placed in the empty bag by someone other than the owner, the goods that have been shunted to the pocket dimension cannot be accessed unless the new item is removed. A bag of concealment registers as nonmagical unless successfully identified, as per a permanent version of the spell magic aura. The mouth of a bag of concealment can be stretched to up to four times its normal width, so larger goods may be hidden inside.","requirements":"Craft Wondrous Items, fabricate, magic aura, secret chest","cost":10000,"destruction":null,"base_item":null,"magic_items":null,"source":"Classic Treasures","pfs_content":0},{"name":"Bag of Holding, Minor","aura_strength":"moderate","aura_school":"conjuration","cl":9,"slots":["none"],"groups":["Wondrous Item"],"price":1000,"weight":3,"description":"The bag of holding opens into a nondimensional space: its inside is larger than its outside dimensions. Regardless of what is put into the bag, it weighs a fixed amount. The limit of this bag's contents is 50 lbs. and 6 cubic ft.\n\nIf a bag of holding is overloaded, or if sharp objects pierce it (from inside or outside), the bag immediately ruptures and is ruined, and all contents are lost forever. If a bag of holding is turned inside out, all of its contents spill out, unharmed, but the bag must be put right before it can be used again. If living creatures are placed within the bag, they can survive for up to 10 minutes, after which time they suffocate. Retrieving a specific item from a bag of holding is a move action, unless the bag contains more than an ordinary backpack would hold, in which case retrieving a specific item is a full-round action. Magic items placed inside the bag don't offer any benefit to the character carrying the bag.\n\nIf a bag of holding is placed within a portable hole, a rift to the Astral Plane is torn in the space: bag and hole alike are sucked into the void and forever lost. If a portable hole is placed within a bag of holding, it opens a gate to the Astral Plane: the hole, the bag, and any creatures within a 10-foot radius are drawn there, destroying the portable hole and bag of holding in the process.","requirements":"Craft Wondrous Items, secret chest","cost":500,"destruction":null,"base_item":null,"magic_items":null,"source":"Classic Treasures","pfs_content":0},{"name":"Corpse-Ferrying Bag","aura_strength":"moderate","aura_school":"conjuration and necromancy","cl":9,"slots":["none"],"groups":["Wondrous Item"],"price":4000,"weight":3,"description":"This large black leather bag has a wide mouth and laces to help keep it shut. It weighs 20 pounds and can carry up to 300 pounds or 10 cubic feet of material (easily able to hold a single Medium corpse or two Small corpses, including their gear). Anything within the bag is protected by a gentle repose spell.","requirements":"Craft Wondrous Items, gentle repose, secret chest","cost":2000,"destruction":null,"base_item":null,"magic_items":null,"source":"Classic Treasures","pfs_content":0},{"name":"Cube of Varied Force Walls","aura_strength":"moderate","aura_school":"evocation","cl":10,"slots":["none"],"groups":["Wondrous Item"],"price":56000,"weight":0.5,"description":"This cube functions exactly like a cube of force except that each wall of the cube can be activated independently and can even have different effects. For example, one wall can block living matter, another wall can block magic, and a third can keep out gases, while the other sides are open without any protection. Activating each wall costs the price of activating that effect for an entire standard cube of force-for instance, one wall against magic and one wall against living matter cost a total of 7 charges per minute.","requirements":"Craft Wondrous Items, wall of force","cost":28000,"destruction":null,"base_item":null,"magic_items":null,"source":"Classic Treasures","pfs_content":0}];
